import{updateBlocks}from"../pages/BlocksPage/BlocksPage";import{updateOverview}from"../pages/OverviewPage/OverviewPage";import{updateSettings}from"../pages/SettingsPage/SettingsPage";import{AppState}from"../store/AppState";export function initPollingService(){window.setInterval(function(){if(moment().seconds()>=6&&AppState.lastRefreshedMinute!==moment().minutes()||AppState.specialSeconds.indexOf(moment().seconds())>=0)try{switch(updateOverview(),$(".page-sidebar-menu>li.active")[0].id){case"page-blocks":updateBlocks(!1);break;case"page-settings":updateSettings(!1)}}catch(e){}},1e3)}